using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class ActorProjectSaveOperations:RefCounted
{
    private readonly ActorProjectFilePickerOperations _picker=new();private readonly Expression _filename=new();
    public ActorProjectSaveOperations(){_filename.Parse("name.validate_filename()",new[]{"name"});}
    private string Clean(string name)=>_filename.Execute(new Godot.Collections.Array{name}).AsString();
    private static string Text(Node owner,string key)=>owner.Get(key).AsString();
    public StyleBoxFlat box(Color background,Color border,int radius,int width){var style=new StyleBoxFlat{BgColor=background,BorderColor=border,ContentMarginLeft=10,ContentMarginRight=10,ContentMarginTop=9,ContentMarginBottom=9};style.SetBorderWidthAll(width);style.SetCornerRadiusAll(radius);return style;}
    public void rebuild_tree(Node owner){var tree=owner.Get("folders").As<Tree>();tree.Clear();var root=tree.CreateItem();root.SetText(0,Text(owner,"project_root").GetFile());root.SetIcon(0,ActorProjectFilePickerOperations.FolderIcon);root.SetIconMaxWidth(0,18);root.SetMetadata(0,owner.Get("project_root"));root.SetMeta("is_file",false);root.Collapsed=false;add_tree_entries(owner,root,Text(owner,"project_root"));tree.SetSelected(root,0);}
    public void add_tree_entries(Node owner,TreeItem parent,string directory)
    {
        var names=DirAccess.GetDirectoriesAt(directory);Array.Sort(names,StringComparer.Ordinal);foreach(string name in names){if(name.StartsWith(".",StringComparison.Ordinal))continue;using var access=DirAccess.Open(directory);if(access!=null&&access.IsLink(name))continue;string path=directory.PathJoin(name).SimplifyPath();var item=owner.Get("folders").As<Tree>().CreateItem(parent);item.SetText(0,name);item.SetIcon(0,ActorProjectFilePickerOperations.FolderIcon);item.SetIconMaxWidth(0,18);item.SetMetadata(0,path);item.SetMeta("is_file",false);add_tree_entries(owner,item,path);}names=DirAccess.GetFilesAt(directory);Array.Sort(names,StringComparer.Ordinal);foreach(string name in names){if(name.GetExtension().ToLowerInvariant()!=Text(owner,"extension"))continue;var item=owner.Get("folders").As<Tree>().CreateItem(parent);item.SetText(0,name);item.SetIcon(0,ActorProjectFilePickerOperations.FileIcon);item.SetIconMaxWidth(0,18);item.SetMetadata(0,directory.PathJoin(name).SimplifyPath());item.SetMeta("is_file",true);}
    }
    public void tree_selected(Node owner){var item=owner.Get("folders").As<Tree>().GetSelected();if(item==null)return;string path=item.GetMetadata(0).AsString().SimplifyPath();if(item.GetMeta("is_file",false).AsBool()){select_existing_path(owner,path);return;}if(ActorProjectFilePickerOperations.Inside(Text(owner,"project_root"),path)&&DirAccess.DirExistsAbsolute(path)){owner.Set("selected_directory",path);refresh_files(owner);validate(owner);}}
    public void tree_activated(Node owner){var item=owner.Get("folders").As<Tree>().GetSelected();if(item!=null&&item.GetMeta("is_file",false).AsBool())select_existing_path(owner,item.GetMetadata(0).AsString());}
    public void refresh_files(Node owner){var files=owner.Get("files").As<ItemList>();if(files==null)return;int generation=owner.Get("_file_generation").AsInt32()+1;owner.Set("_file_generation",generation);files.Clear();var paths=new List<string>();foreach(string name in DirAccess.GetFilesAt(Text(owner,"selected_directory")))if(name.GetExtension().ToLowerInvariant()==Text(owner,"extension"))paths.Add(Text(owner,"selected_directory").PathJoin(name).SimplifyPath());paths.Sort(StringComparer.Ordinal);foreach(string path in paths){int index=files.AddItem(path.GetFile(),ActorProjectFilePickerOperations.FileIcon);files.SetItemMetadata(index,path);owner.Call("_load_thumbnail",path,index,generation);}if(paths.Count==0){files.AddItem("No ."+Text(owner,"extension")+" resources in this folder");files.SetItemDisabled(0,true);}owner.Get("breadcrumb").As<Label>().Text=Text(owner,"selected_directory")==Text(owner,"project_root")?"Project":"Project  /  "+_picker.relative_to_project(owner,Text(owner,"selected_directory")).Replace("/","  /  ");}
    public void thumbnail_complete(Node owner,string path,int index,int generation,Texture2D? thumbnail){if(thumbnail!=null)owner.Get("_thumbnail_cache").AsGodotDictionary()[path]=thumbnail;var files=owner.Get("files").As<ItemList>();if(GodotObject.IsInstanceValid(files)&&generation==owner.Get("_file_generation").AsInt32()&&thumbnail!=null&&index>=0&&index<files.ItemCount&&files.GetItemMetadata(index).AsString()==path)files.SetItemIcon(index,thumbnail);}
    public void existing_file_selected(Node owner,int index){var files=owner.Get("files").As<ItemList>();if(index>=0&&index<files.ItemCount&&!files.IsItemDisabled(index))select_existing_path(owner,files.GetItemMetadata(index).AsString());}
    public void select_existing_path(Node owner,string path){path=path.SimplifyPath();owner.Set("selected_directory",path.GetBaseDir());owner.Get("filename").As<LineEdit>().Text=path.GetFile().GetBaseName();refresh_files(owner);validate(owner);}
    public string target_path(Node owner)=>Text(owner,"selected_directory").PathJoin(Clean(owner.Get("filename").As<LineEdit>().Text.Trim())+"."+Text(owner,"extension")).SimplifyPath();
    public void validate(Node owner)
    {
        var filename=owner.Get("filename").As<LineEdit>();var destination=owner.Get("destination").As<Label>();var status=owner.Get("status").As<Label>();var save=owner.Get("save_button").As<Button>();if(filename==null||destination==null||status==null||save==null)return;string raw=filename.Text.Trim(),clean=Clean(raw),target=target_path(owner);bool exists=Godot.FileAccess.FileExists(target);var toggle=owner.Get("embedded_toggle").As<CheckButton>();bool embedding=owner.Get("allow_embedded").AsBool()&&toggle!=null&&toggle.ButtonPressed;filename.Editable=!embedding;foreach(var control in new Control[]{owner.Get("folders").As<Tree>(),owner.Get("files").As<ItemList>()}){control.MouseFilter=embedding?Control.MouseFilterEnum.Ignore:Control.MouseFilterEnum.Stop;control.Modulate=embedding?new Color(1,1,1,.42f):Colors.White;}if(embedding){save.Disabled=false;save.Text="Use embedded";destination.Text="Stored inside this actor";destination.TooltipText="No project file will be created";status.Text="The resource will travel with the actor until you save it later.";status.AddThemeColorOverride("font_color",new Color("80dbc4"));return;}save.Text="Save resource";save.Disabled=clean.Length==0||clean!=raw||!ActorProjectFilePickerOperations.Inside(Text(owner,"project_root"),target)||exists;destination.Text="Project  /  "+_picker.relative_to_project(owner,target);destination.TooltipText=target;status.Text=exists?"A resource with this name already exists in this folder.":clean.Length==0||clean!=raw?"Enter a valid file name.":"Ready to save inside the project.";status.AddThemeColorOverride("font_color",new Color(exists?"ff9b91":clean.Length==0||clean!=raw?"ffca80":"80dbc4"));
    }
    public void save(PopupPanel owner){validate(owner);if(owner.Get("save_button").As<Button>().Disabled)return;var toggle=owner.Get("embedded_toggle").As<CheckButton>();bool embed=owner.Get("allow_embedded").AsBool()&&toggle!=null&&toggle.ButtonPressed;resolve(owner,new Settings{["cancelled"]=false,["embedded"]=embed,["path"]=embed?"":target_path(owner)});}
    public void resolve(PopupPanel owner,Variant result){if(owner.Get("_resolved").AsBool())return;owner.Set("_resolved",true);if(result.VariantType==Variant.Type.String)owner.EmitSignal("finished",new Settings{["cancelled"]=result.AsString().Length==0,["embedded"]=false,["path"]=result});else owner.EmitSignal("finished",result);owner.Hide();}
}
